        note: "<b>Zayıf bir ilişki, kayıt defterini çürütmez.</b> Yerleşim siyasi konumu " + "ölçer, davranış profili ise yazma alışkanlığını — ve bu sitenin 05 numaralı " + "bulgusu bu ikisinin zaten farklı şeyler olduğunu gösteriyor. Buradaki sonuç " + "“kayıt defteri yanlış” demek değil, “bu dönemdeki haberler onu bağımsız olarak doğrulayamıyor” " + "demektir. İkisi aynı şey değildir ve tablo, hangi çiftlerin ayrıştığını " + "gizlemeden gösteriyor.",
        body: reg.surprising.length ? '<div class="scroller panel"><table><thead><tr>' + "<th>Kurum çifti</th><th class=\"r\">Yerleşim farkı</th>" + "<th class=\"r\">Yazma biçimi farkı</th><th>Okuma</th></tr></thead><tbody>" + reg.surprising.map(function (p) {
          return "<tr><td><b>" + runtime.esc(runtime.SRC[p.a].n) + "</b> ↔ <b>" + runtime.esc(runtime.SRC[p.b].n) + "</b></td>" + '<td class="r num">' + p.leanGap + " puan</td>" + '<td class="r num" style="color:var(--hot)">' + p.dist.toFixed(3) + "</td>" + '<td style="color:var(--ink2);font-size:12.5px">Kayıt defteri uzak ' + "konumlandırıyor, başlık davranışı ise en yakın çiftlerden</td></tr>";
        }).join("") + "</tbody></table></div>" + '<p style="margin-top:10px;font-size:12.5px;color:var(--muted)">Yazma biçimi ' + "farkı, iki kurumun yapı kullanım oranları arasındaki Öklid mesafesidir; " + "küçük değer benzer demektir.</p>" : "",
